SELECT id,name,song_count,duration,size FROM albums WHERE id IN ('pending-uploads','al-86f72c214f','al-ruler-mirror-b-edition') ORDER BY id;
SELECT COUNT(*) AS count,COALESCE(SUM(sm.duration),0) AS duration,COALESCE(SUM(si.size),0) AS size FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id WHERE sm.album_id='pending-uploads';
SELECT sm.id master_id,sm.album_id,sm.artist_id,sm.album_artist_id,sm.title,sm.track,sm.disc,sm.duration master_duration,sm.lyrics IS NOT NULL has_lyrics,sm.lyrics_rich IS NOT NULL has_rich_lyrics,sm.cover_r2_key,si.id instance_id,si.source_id,si.source_type,si.storage_uri,si.suffix,si.size instance_size,si.duration instance_duration,si.missing,si.tag_scanned,si.storage_object_id,si.source_etag,se.id entry_id,se.source_id entry_source_id,se.parent_id,se.path,se.display_name,se.kind,se.object_id,se.companion_of,so.physical_key,so.legacy_key,so.size object_size,so.etag object_etag,so.suffix object_suffix FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id JOIN storage_entries se ON se.instance_id=si.id JOIN storage_objects so ON so.id=si.storage_object_id WHERE se.parent_id='se-cc9368c480864e68b672b159b2215a01' ORDER BY se.path;
SELECT g.id,g.display_name,m.album_id,m.sort_order FROM album_display_groups g LEFT JOIN album_display_group_members m ON m.group_id=g.id WHERE g.id='ag-ruler-mirror-editions' OR g.display_name='矩尺镜海·蚀刻于此媒介' ORDER BY m.sort_order;
